// compose/certify/mock-fee-plugin/src/main/java/pe/gob/mtc/mock/MockFeeDataProviderPlugin.java
//
// Mock del MtcFeeDataProviderPlugin real del MTC — SOLO para el entorno de
// pruebas reproducible de esta PoC. No reemplaza la integración real con el
// Servicio Web FEE (ExternalToken / ObtenerInformacionLicenciaPersona).
//
// Implementa la interfaz SPI real de Inji Certify; firma confirmada con
// `javap -p` sobre el JAR extraído de la imagen
// `injistack/inji-certify-with-plugins:0.14.0`
// (ver compose/certify/mock-fee-plugin/lib/certify-integration-api-0.14.0.jar):
//
//   public interface io.mosip.certify.api.spi.DataProviderPlugin {
//     JSONObject fetchData(Map<String, Object> identityDetails)
//         throws DataProviderExchangeException;
//   }
//
// Devuelve driving_privileges con la forma que ISO/IEC 18013-5 Table 3 exige:
// un array de objetos con vehicle_category_code/issue_date/expiry_date por
// categoría. Esta forma es una SUPOSICIÓN sobre lo que devuelve el FEE real y
// debe confirmarse contra el FEE antes de escribir el plugin de producción.
//
// Restricciones de Inji Certify 0.14.0 confirmadas contra el flujo OID4VCI
// pre-auth real (ver compose/scripts/run-e2e.sh):
//
// 1. La key de identityDetails con el identificador del titular es "sub", cuyo
//    VALOR es el string JSON de las claims enviadas en
//    POST /v1/certify/pre-authorized-data (p. ej.
//    {sub={"org.iso.18013.5.1":{"document_number":"MOCK-1CAT"}}, aud=...,
//    c_nonce=..., ...}): es el claim "sub" del access token de pre-auth. Otros
//    flujos (auth-code con identity system) pueden poblar individualId.
//
// 2. driving_privileges debe (a) viajar como STRING JSON, no JSONArray, y
//    (b) fetchData() debe devolver sus campos DUPLICADOS: anidados bajo el
//    namespace ISO ("org.iso.18013.5.1") y planos en el nivel superior.
//    Causa de (a), por decompilación de
//    io.mosip.certify.utils.CredentialUtils.toJsonMap: un valor String
//    top-level pasa por JSONObject.wrap(value), que si empieza con '[' o '{'
//    lo reparsea como JSONArray/JSONObject real. Causa de (b), por
//    decompilación de
//    io.mosip.certify.services.CertifyIssuanceServiceImpl.getVerifiableCredential:
//    `templateParams.putAll(jsonObject.toMap())` mezcla el JSONObject PLANO,
//    y `rootContext = new HashMap(templateParams)` se construye antes de
//    toJsonMap, así que rootContext solo tiene la key anidada
//    "org.iso.18013.5.1" si fetchData() la incluye. render-mdoc-template.mjs
//    genera el marcador ${rootContext['org.iso.18013.5.1'].driving_privileges}
//    (Velocity, SIN comillas alrededor, a diferencia de los demás campos) y
//    espera esa key anidada. Sin ella el JSON resultante queda inválido y
//    POST /v1/certify/issuance/credential falla con "ERROR_SIGNING_QR_DATA":
//      org.json.JSONException: Expected a ',' or '}' at 1280
//        [character 83 line 13]
//      en io.mosip.certify.vcformatters.VelocityTemplatingEngineImpl.format
package pe.gob.mtc.mock;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.json.JSONArray;
import org.json.JSONObject;
import org.springframework.stereotype.Component;

import io.mosip.certify.api.exception.DataProviderExchangeException;
import io.mosip.certify.api.spi.DataProviderPlugin;

/**
 * Implementación mínima del SPI {@link DataProviderPlugin} de Inji Certify,
 * con datos sintéticos fijos — no reemplaza la integración real con el FEE.
 *
 * <p><b>{@code @Component}</b> registra la clase como bean, combinado con
 * {@code mosip.certify.integration.scan-base-package=pe.gob.mtc.mock} y
 * {@code mosip.certify.integration.data-provider-plugin=MockFeeDataProviderPlugin}
 * (ambos en {@code certify-mtc-mock-fee.properties}). Se confirmó contra un
 * {@code docker compose up} real que el nombre del bean coincide con el que
 * Inji Certify busca.
 *
 * <p><b>Key de {@code identityDetails}:</b> es {@code "sub"}, cuyo valor es
 * el string JSON de las claims enviadas en
 * {@code POST /v1/certify/pre-authorized-data} (p. ej.
 * {@code {"org.iso.18013.5.1":{"document_number":"MOCK-1CAT"}}}). Este mock
 * extrae {@code document_number} de ese JSON; si falla, cae a
 * {@code individualId}/{@code individual_id}/{@code document_number} planos
 * (otros flujos pueden poblar identityDetails así) y finalmente a un valor
 * por defecto determinístico.
 */
@Component("MockFeeDataProviderPlugin")
public class MockFeeDataProviderPlugin implements DataProviderPlugin {

    private static final String DEFAULT_DOCUMENT_NUMBER = "MOCK-1CAT";
    private static final String NAMESPACE = "org.iso.18013.5.1";

    // Selfie real (480x640, JPEG ~48KB en base64): inji-wallet exige un paso de
    // "Face Verification" (selfie en vivo comparada contra este portrait)
    // antes de compartir por OpenID4VP, y con un JPEG sin rostro falla
    // ("Face verification failed!", confirmado empíricamente).
    private static final String MOCK_PORTRAIT_BASE64 =
        "";

    // Extrae "document_number":"<valor>" de un fragmento JSON crudo sin
    // necesidad de un parser JSON completo — identityDetails.get("sub")
    // llega como String, y esta clase ya no quiere depender de más
    // librerías de las estrictamente necesarias para un mock.
    private static final Pattern DOCUMENT_NUMBER_IN_SUB = Pattern.compile(
        "\"document_number\"\\s*:\\s*\"([^\"]+)\"");

    @Override
    public JSONObject fetchData(Map<String, Object> identityDetails) throws DataProviderExchangeException {
        String documentNumber = resolveDocumentNumber(identityDetails);

        JSONObject nsSubject = new JSONObject();
        nsSubject.put("family_name", "PRUEBA");
        nsSubject.put("given_name", "OPERADOR MTC");
        nsSubject.put("birth_date", "1990-05-20");
        nsSubject.put("issue_date", "2024-01-01");
        nsSubject.put("expiry_date", "2029-01-01");
        nsSubject.put("issuing_country", "PE");
        nsSubject.put("issuing_authority", "MTC");
        nsSubject.put("document_number", documentNumber);
        nsSubject.put("portrait", MOCK_PORTRAIT_BASE64);
        nsSubject.put("un_distinguishing_sign", "PE");
        // portrait se incluye siempre: la plantilla Velocity de
        // credential_config declara portrait con el marcador
        // ${rootContext[...].portrait}, y si el campo se omite ese marcador
        // queda literal dentro del mDL (inji-wallet lo muestra como una URI de
        // imagen rota). Certify sin modificar no decodifica este base64
        // (preprocessForCBOR, confirmado por bytecode); el parche de
        // certify/patched-jars lo decodifica a bytes y lo escribe como CBOR
        // bstr conforme a ISO 18013-5, en vez de tstr — ver
        // certify/patched-jars/README.md.
        //
        // driving_privileges viaja como STRING JSON (no JSONArray real) — ver
        // el encabezado del archivo, punto 2(a).
        nsSubject.put("driving_privileges", drivingPrivilegesFor(documentNumber).toString());

        // Campos DUPLICADOS: anidados bajo el namespace ISO (lo que necesita el
        // marcador Velocity ${rootContext['org.iso.18013.5.1'].X}) y planos en
        // el nivel superior (lo que CertifyIssuanceServiceImpl mezcla en
        // templateParams vía jsonObject.toMap()). Ver el encabezado, punto
        // 2(b).
        JSONObject subject = new JSONObject();
        subject.put(NAMESPACE, nsSubject);
        for (String key : nsSubject.keySet()) {
            subject.put(key, nsSubject.get(key));
        }
        return subject;
    }

    /**
     * Busca el identificador del titular. Primero intenta la key "sub" (con
     * el document_number embebido en su valor JSON) y, si no está o no se
     * puede extraer, cae a individualId/individual_id/document_number de
     * otros flujos — ver el comentario de clase.
     */
    private static String resolveDocumentNumber(Map<String, Object> identityDetails) {
        if (identityDetails != null) {
            Object sub = identityDetails.get("sub");
            if (sub != null) {
                Matcher m = DOCUMENT_NUMBER_IN_SUB.matcher(sub.toString());
                if (m.find()) {
                    return m.group(1);
                }
            }
            for (String key : new String[] {"individualId", "individual_id", "document_number"}) {
                Object value = identityDetails.get(key);
                if (value != null && !value.toString().isBlank()) {
                    return value.toString();
                }
            }
        }
        return DEFAULT_DOCUMENT_NUMBER;
    }

    /**
     * Categorías sintéticas por número de documento de prueba.
     * "MOCK-1CAT" -> 1 categoría, "MOCK-4CAT" -> 4 categorías — para que el
     * script end-to-end (compose/scripts/run-e2e.sh) pueda emitir ambos casos
     * sin cambiar el      * plugin.
     */
    static JSONArray drivingPrivilegesFor(String documentNumber) {
        int count = documentNumber != null && documentNumber.endsWith("4CAT") ? 4 : 1;
        String[] categories = {"A-I", "A-IIa", "A-IIb", "B-IIc"};
        JSONArray out = new JSONArray();
        for (int i = 0; i < count; i++) {
            JSONObject priv = new JSONObject();
            priv.put("vehicle_category_code", categories[i]);
            priv.put("issue_date", "2020-01-15");
            priv.put("expiry_date", "2030-01-15");
            out.put(priv);
        }
        return out;
    }

}
